package net.zartra.gui;
import java.io.File;import java.util.*;import java.util.logging.Logger;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;import static org.junit.Assert.*;
public class Goal2ConditionStorageTest {@Test public void conditionMetadataRoundTrips()throws Exception{File dir=new File(System.getProperty("java.io.tmpdir"),"zgui-cond-"+System.nanoTime());MenuStorage s=new MenuStorage(dir,Logger.getLogger("test"));MenuDefinition m=new MenuDefinition("cond","Cond",3);MenuItem i=new MenuItem(new ItemStack(Material.STONE),null);ActionEntry a=new ActionEntry();a.type="MESSAGE";a.value="ok";a.conditionMode=ConditionSet.Mode.OR;a.conditionFailureMessage="no";ConditionEntry c=new ConditionEntry(ConditionEntry.Type.PLAYER_NAME,"Alex");c.order=4;c.enabled=false;c.inverted=true;c.failureMessage="bad";a.conditions.add(c);i.actions(MenuClickType.LEFT).add(a);m.items.put(0,i);s.save(m);ActionEntry r=s.load().get("cond").items.get(0).actions(MenuClickType.LEFT).get(0);assertEquals(ConditionSet.Mode.OR,r.conditionMode);assertEquals("no",r.conditionFailureMessage);ConditionEntry rc=r.conditions.get(0);assertEquals(4,rc.order);assertFalse(rc.enabled);assertTrue(rc.inverted);assertEquals("bad",rc.failureMessage);}}